using System.Data;
using System.Globalization;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Storage;
using Shop.SharedKernel;
namespace Shop.Modules.Credit;
public sealed class CreditClearanceService(CreditDbContext db,ICreditOrderScheduleSource sourceReader,CreditScheduleService schedules,CreditUpfrontService upfront,ChequeApprovalService approvals,ICreditOrderCommitments commitments,ICreditClearanceProtection protection,TimeProvider clock):ICreditFulfillmentAuthorization
{
    private sealed record Seal(string Id,string OwnerId,string OrderId,string ActorId,int Sequence,string Action,string State,string? PreviousVersion,string SourceOrderVersion,string ResultOrderVersion,CreditClearanceEvidence Evidence,string EvidenceFingerprint,string Note,bool InitialCommit,DateTimeOffset RecordedAt,[property:System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingDefault)]bool AcknowledgedPartialDispatch=false);
    private static string Json<T>(T v)=>JsonSerializer.Serialize(v,CreditScheduleFacts.Json);
    private static string Hash<T>(T v)=>CreditApplicationRules.Hash(Json(v));
    private void Root(){if(db.Database.CurrentTransaction?.GetDbTransaction().IsolationLevel!=IsolationLevel.Serializable)throw new InvalidOperationException("Credit financial clearance requires the shared Sales/Credit/Inventory audited Serializable transaction.");}
    private async Task<CreditOrderScheduleSource> Source(string owner,string order,CancellationToken ct){Root();owner=CreditApplicationRules.Actor(owner);CreditApplicationRules.Id(order);await schedules.PageAsync(owner,order,false,ct);var s=await sourceReader.LockAndReadAsync(owner,order,ct);if(s.OwnerId!=owner||s.OrderId!=order)throw CreditClearanceRules.Unavailable();return s;}
    private IQueryable<CreditClearanceEvent> Events(string owner,string order)=>db.ClearanceEvents.FromSqlInterpolated($"SELECT * FROM [credit].[ClearanceEvents] WITH (READCOMMITTEDLOCK) WHERE [OwnerId]={owner} AND [OrderId]={order}").AsNoTracking();
    private IQueryable<CreditClearanceCommand> Commands=>db.ClearanceCommands.FromSqlRaw("SELECT * FROM [credit].[ClearanceCommands] WITH (READCOMMITTEDLOCK)").AsNoTracking();
    private T Decode<T>(string purpose,string principal,string order,string id,byte[] bytes){try{return JsonSerializer.Deserialize<T>(protection.Unprotect(purpose,principal,order,id,bytes),CreditScheduleFacts.Json)??throw CreditClearanceRules.Unavailable();}catch(Exception e)when(e is JsonException or NullReferenceException){throw CreditClearanceRules.Unavailable();}}
    private static CreditClearanceSummary Summary(CreditClearanceEvent e,Seal s)=>new(e.Id,e.OrderId,e.Sequence,e.Action,e.State,Convert.ToBase64String(e.Version),s.EvidenceFingerprint,s.SourceOrderVersion,s.ResultOrderVersion,e.RecordedAt);
    private CreditClearanceResult Receipt(CreditClearanceCommand c)
    {
        var raw=protection.Unprotect("receipt",c.ActorId,c.OrderId,c.CommandId,c.ProtectedResult);try{var r=JsonSerializer.Deserialize<CreditClearanceResult>(raw,CreditScheduleFacts.Json)??throw CreditClearanceRules.Unavailable();var s=r.Event.Summary;if(CreditApplicationRules.Hash(raw)!=c.ResultHash||r.SchemaVersion!=1||r.Replayed||r.CommandId!=c.CommandId||r.OrderId!=c.OrderId||s.Id!=c.EventId||s.OrderId!=c.OrderId||s.RecordedAt!=c.At||s.BankVerified||r.BankVerified||r.CanPay)throw CreditClearanceRules.Unavailable();CreditApplicationRules.Version(s.Version);CreditApplicationRules.Version(s.SourceOrderVersion);CreditApplicationRules.Version(s.ResultOrderVersion);CreditApplicationRules.Digest(s.EvidenceFingerprint);return r;}catch(Exception e)when(e is JsonException or NullReferenceException){throw CreditClearanceRules.Unavailable();}
    }
    private async Task<CreditClearanceEventData[]> History(CreditOrderScheduleSource source,CancellationToken ct)
    {
        var rows=await Events(source.OwnerId,source.OrderId).OrderBy(x=>x.Sequence).Take(201).ToArrayAsync(ct);if(rows.Length>200)throw CreditClearanceRules.Unavailable();var cmds=await Commands.Where(x=>x.OwnerId==source.OwnerId&&x.OrderId==source.OrderId).Take(201).ToArrayAsync(ct);if(cmds.Length!=rows.Length)throw CreditClearanceRules.Unavailable();var result=new List<CreditClearanceEventData>();
        foreach(var e in rows){var s=Decode<Seal>("event",source.OwnerId,source.OrderId,e.Id,e.ProtectedEvent);var past=result.LastOrDefault();if(s.Id!=e.Id||s.OwnerId!=source.OwnerId||s.OrderId!=source.OrderId||s.ActorId!=e.ActorId||CreditApplicationRules.Actor(e.ActorId)!=e.ActorId||s.Sequence!=result.Count+1||s.Sequence!=e.Sequence||s.Action!=e.Action||s.State!=e.State||s.PreviousVersion!=past?.Summary.Version||s.RecordedAt!=e.RecordedAt||e.RecordedAt.Offset!=TimeSpan.Zero||e.RecordedAt<(past?.Summary.RecordedAt??source.CreatedAt)||e.Version.Length!=8||s.Evidence.FinancialFingerprint!=CreditScheduleFacts.FinancialHash(source)||s.Evidence.QuoteFingerprint!=source.QuoteFingerprint||Hash(s.Evidence)!=s.EvidenceFingerprint||s.InitialCommit!=(e.Sequence==1)||s.InitialCommit&&e.RecordedAt>=source.ExpiresAt)throw CreditClearanceRules.Unavailable();
            if(s.AcknowledgedPartialDispatch&&s.InitialCommit)throw CreditClearanceRules.Unavailable();CreditUpfrontRules.Text(s.Note,500,!s.AcknowledgedPartialDispatch);CreditApplicationRules.Version(s.SourceOrderVersion);CreditApplicationRules.Version(s.ResultOrderVersion);
            if(s.Action=="Approve"?(s.State!="Approved"||!CreditClearanceRules.Eligible(s.Evidence)||past is{Summary.State:"Approved"}&&past.Summary.EvidenceFingerprint==s.EvidenceFingerprint):(s.Action!="Revoke"||s.State!="Revoked"||past?.Summary.State!="Approved"))throw CreditClearanceRules.Unavailable();
            var data=new CreditClearanceEventData(Summary(e,s),s.Note,s.PreviousVersion,s.AcknowledgedPartialDispatch);var cmd=cmds.SingleOrDefault(x=>x.EventId==e.Id)??throw CreditClearanceRules.Unavailable();var receipt=Receipt(cmd);if(cmd.ActorId!=e.ActorId||cmd.At!=e.RecordedAt||receipt.InitialCommit!=s.InitialCommit||Json(receipt.Event)!=Json(data))throw CreditClearanceRules.Unavailable();result.Add(data);
        }return result.ToArray();
    }
    private async Task<CreditClearanceEvidence> Evidence(CreditOrderScheduleSource s,CancellationToken ct)
    {
        var plan=await schedules.PageAsync(s.OwnerId,s.OrderId,false,ct);var u=await upfront.PageAsync(s.OwnerId,s.OrderId,false,ct);var a=await approvals.PageAsync(s.OwnerId,s.OrderId,ct);var amount=CreditUpfrontRules.Rial(CreditUpfrontRules.Required(s.PayableTotalRial,s.Installments.Select(x=>x.AmountRial).ToArray()));if(u.RequiredAmountRial!=amount||a.ScheduleVersion!=plan.Current?.Version||u.ScheduleVersion!=plan.Current?.Version)throw CreditClearanceRules.Unavailable();var confirmed=u.Current is{}v&&v.RequiredAmountRial==amount&&v.AcknowledgedAmountRial==amount&&(amount=="0"?v.State=="NoUpfrontDue":v.State=="ReceiptConfirmed");
        return new(CreditScheduleFacts.FinancialHash(s),s.QuoteFingerprint,plan.Current?.Id,plan.Current?.Version,amount,u.Current?.Id,u.Current?.Version,u.Current?.State,confirmed,a.Items.Select(x=>new CreditClearanceCheque(x.Sequence,x.DueDate,x.AmountRial,x.Cheque?.Id,x.Cheque?.Version,x.Cheque?.State,x.Current?.Id,x.Current?.Version,x.ApprovedForCurrentCheque)).ToArray(),a.AllChequesApproved);
    }
    public async Task<CreditClearancePage> PageAsync(string owner,string order,bool writable,CancellationToken ct)
    {
        var s=await Source(owner,order,ct);var evidence=await Evidence(s,ct);var history=await History(s,ct);var current=history.LastOrDefault()?.Summary;var status=await commitments.ReadAsync(s.OwnerId,order,ct);if(status.OrderId!=order||status.OrderVersion!=s.OrderVersion||status.State!=s.State)throw CreditClearanceRules.Conflict();var fingerprint=Hash(evidence);var effective=current is{State:"Approved"}&&current.EvidenceFingerprint==fingerprint&&CreditClearanceRules.Eligible(evidence);var blockers=new List<string>();var initial=s.State=="AwaitingPayment";var amendable=status.ShipmentState is null or"packed"||status.HasRemainingPartialDispatch;
        if(initial?s.ExpiresAt<=clock.GetUtcNow():s.State!="CreditApproved")blockers.Add("order_closed");if(status.ReservationState!=(initial?"Active":"Allocated"))blockers.Add("reservation_not_ready");if(!amendable)blockers.Add("shipment_already_dispatched");if(!evidence.UpfrontConfirmed)blockers.Add("upfront_confirmation_required");if(!evidence.AllChequesApproved||evidence.Cheques.Length==0)blockers.Add("all_current_cheques_required");if(evidence.ScheduleVersion is null)blockers.Add("schedule_required");if(s.State=="CreditApproved"&&history.Length==0)blockers.Add("clearance_history_required");if(history.Length>=200)blockers.Add("history_capacity");var preview=Hash(new{Contract="Sayman.Credit.ClearancePreview.v1",OrderVersion=s.OrderVersion,CurrentVersion=current?.Version,Status=status,EvidenceFingerprint=fingerprint});
        return new(1,order,s.OrderVersion,s.State,status.ReservationState,status.ShipmentState,evidence,fingerprint,preview,current,effective,writable&&blockers.Count==0&&!effective,writable&&amendable&&s.State=="CreditApproved"&&history.Length<200&&current?.State=="Approved",blockers.ToArray());
    }
    public async Task<CreditClearanceCustomerPage> CustomerAsync(string owner,string order,CancellationToken ct){var p=await PageAsync(owner,order,false,ct);return new(1,order,p.OrderState,p.Current,p.Effective);}
    public async Task<bool> IsAuthorizedAsync(string owner,string order,CancellationToken ct)=>(await ReadAuthorityAsync(owner,order,ct)).Authorized;
    public async Task<CreditDispatchAuthority> ReadAuthorityAsync(string owner,string order,CancellationToken ct){var p=await PageAsync(owner,order,false,ct);var status=await commitments.ReadAsync(owner,order,ct);var effective=p.OrderState=="CreditApproved"&&p.ReservationState=="Allocated"&&(p.ShipmentState is null or"packed"||status.HasRemainingPartialDispatch)&&p.Effective;return new(effective,effective?p.Current?.RecordedAt:null);}
    public async Task<CreditClearanceHistory> HistoryAsync(string owner,string order,int? before,CancellationToken ct){if(before is<=0 or>200)throw CreditClearanceRules.Invalid();var s=await Source(owner,order,ct);var rows=(await History(s,ct)).Reverse().Where(x=>before is null||x.Summary.Sequence<before).Take(21).ToArray();return new(1,order,rows.Take(20).ToArray(),rows.Length>20?rows[19].Summary.Sequence:null);}
    public async Task<CreditClearanceResult> WriteAsync(string actor,string owner,string order,string command,CreditClearanceInput input,CancellationToken ct)
    {
        actor=CreditApplicationRules.Actor(actor);owner=CreditApplicationRules.Actor(owner);CreditApplicationRules.Id(order);CreditApplicationRules.Id(command);CreditClearanceRules.Validate(input);var source=await Source(owner,order,ct);await Gate(actor,command,ct);var hash=Hash(new{Contract="Sayman.Credit.ClearanceCommand.v1",Owner=owner,OrderId=order,Input=input});var prior=await Commands.SingleOrDefaultAsync(x=>x.ActorId==actor&&x.CommandId==command,ct);if(prior is not null){if(prior.OwnerId!=owner||prior.OrderId!=order||prior.PayloadHash!=hash)throw new BusinessException("credit_clearance_idempotency_conflict","This clearance UUID has different intent.");return Receipt(prior)with{Replayed=true};}
        var page=await PageAsync(owner,order,true,ct);var status=await commitments.ReadAsync(owner,order,ct);if(input.AcknowledgedPartialDispatch!=status.HasRemainingPartialDispatch)throw CreditClearanceRules.Conflict();if(input.OrderVersion!=page.OrderVersion||input.Version!=page.Current?.Version||input.PreviewFingerprint!=page.PreviewFingerprint||(input.Action=="Approve"?!page.CanApprove:!page.CanRevoke))throw CreditClearanceRules.Conflict();var at=clock.GetUtcNow().ToUniversalTime();if(at<(page.Current?.RecordedAt??source.CreatedAt))throw CreditClearanceRules.Conflict();var initial=page.Current is null;string resultVersion=source.OrderVersion;
        if(input.Action=="Approve"){var result=await commitments.CommitAsync(new(owner,order,source.OrderVersion,source.QuoteFingerprint,source.PayableTotalRial,actor,at),ct);if(result.State!="CreditApproved"||result.ReservationState!="Allocated")throw CreditClearanceRules.Conflict();resultVersion=result.OrderVersion;}
        var e=new CreditClearanceEvent{OwnerId=owner,OrderId=order,ActorId=actor,Sequence=(page.Current?.Sequence??0)+1,Action=input.Action,State=input.Action=="Approve"?"Approved":"Revoked",RecordedAt=at};var seal=new Seal(e.Id,owner,order,actor,e.Sequence,e.Action,e.State,page.Current?.Version,input.OrderVersion,resultVersion,page.Evidence,page.EvidenceFingerprint,input.Note,initial,at,input.AcknowledgedPartialDispatch);e.ProtectedEvent=protection.Protect("event",owner,order,e.Id,Json(seal));db.ClearanceEvents.Add(e);await db.SaveChangesAsync(ct);var data=new CreditClearanceEventData(Summary(e,seal),input.Note,input.Version,input.AcknowledgedPartialDispatch);var receipt=new CreditClearanceResult(1,command,order,data,initial,false);var raw=Json(receipt);db.ClearanceCommands.Add(new(){ActorId=actor,CommandId=command,OwnerId=owner,OrderId=order,EventId=e.Id,PayloadHash=hash,ResultHash=CreditApplicationRules.Hash(raw),ProtectedResult=protection.Protect("receipt",actor,order,command,raw),At=at});await db.SaveChangesAsync(ct);await EnsureCommitAsync(owner,order,receipt,ct);return receipt;
    }
    public async Task EnsureCommitAsync(string owner,string order,CreditClearanceResult result,CancellationToken ct)
    {
        var s=await Source(owner,order,ct);var p=await PageAsync(owner,order,false,ct);var status=await commitments.ReadAsync(owner,order,ct);if(result.Event.AcknowledgedPartialDispatch!=status.HasRemainingPartialDispatch)throw CreditClearanceRules.Conflict();if(p.Current?.Id!=result.Event.Summary.Id||p.Current.Version!=result.Event.Summary.Version||p.OrderVersion!=result.Event.Summary.ResultOrderVersion||p.OrderState!="CreditApproved"||p.ReservationState!="Allocated"||(p.ShipmentState is not(null or"packed")&&!status.HasRemainingPartialDispatch)||result.InitialCommit&&s.ExpiresAt<=clock.GetUtcNow()||result.Event.Summary.Action=="Approve"&&!p.Effective||result.Event.Summary.Action=="Revoke"&&p.Effective)throw CreditClearanceRules.Conflict();
    }
    public async Task<CreditClearanceResult> ReceiptAsync(string actor,string owner,string order,string command,CancellationToken ct){actor=CreditApplicationRules.Actor(actor);owner=CreditApplicationRules.Actor(owner);CreditApplicationRules.Id(order);CreditApplicationRules.Id(command);var c=await Commands.SingleOrDefaultAsync(x=>x.ActorId==actor&&x.CommandId==command&&x.OwnerId==owner&&x.OrderId==order,ct)??throw CreditApplicationRules.Missing();return Receipt(c)with{Replayed=true};}
    private async Task Gate(string actor,string command,CancellationToken ct)
    {
        Root();await using var c=db.Database.GetDbConnection().CreateCommand();c.Transaction=db.Database.CurrentTransaction!.GetDbTransaction();c.CommandTimeout=15;c.CommandText="DECLARE @r int;EXEC @r=sys.sp_getapplock @Resource=@resource,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=10000;SELECT @r;";var p=c.CreateParameter();p.ParameterName="@resource";p.Value="sayman:credit:clearance:v1:"+CreditApplicationRules.Hash(actor+":"+command);c.Parameters.Add(p);if(Convert.ToInt32(await c.ExecuteScalarAsync(ct),CultureInfo.InvariantCulture)<0)throw new BusinessException("credit_clearance_busy","Retry the same financial authorization UUID.");
    }
}
